const decodeBase64Utf8 = (value: string) => {
  const binary = globalThis.atob(value);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return new TextDecoder().decode(bytes);
};

const REFERENCE_SVG_TEMPLATE = decodeBase64Utf8(
  REFERENCE_SVG_TEMPLATE_BASE64,
);

const escapeMarkup = (value: string) =>
  value.replaceAll("&", "&amp;").replaceAll('"', "&quot;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");

const selectConditionalBlocks = (
  markup: string,
  conditions: Readonly<Record<string, boolean>>,
) => {
  const token = /<sc-if\b[^>]*value="{{\s*([A-Za-z0-9_]+)\s*}}"[^>]*>|<\/sc-if>/g;
  const enabled = [true];
  let output = "";
  let cursor = 0;
  let match: RegExpExecArray | null;

  while ((match = token.exec(markup))) {
    if (enabled[enabled.length - 1]) output += markup.slice(cursor, match.index);
    if (match[0].startsWith("</")) {
      enabled.pop();
    } else {
      enabled.push(
        enabled[enabled.length - 1] && Boolean(conditions[match[1]]),
      );
    }
    cursor = token.lastIndex;
  }

  if (enabled[enabled.length - 1]) output += markup.slice(cursor);
  return output;
};

const textForScene = (scene: FinishScene, position: number) => {
  if (scene === "p1") return "TOP STEP · P1";
  if (scene === "podium") return `ON THE PODIUM · P${position === 3 ? 3 : 2}`;
  if (scene === "points") return "IN THE POINTS";
  if (scene === "dnf") return "RETIRED · DNF";
  return "FINISHED · P11+";
};

const accessibleLabel = (scene: FinishScene, position: number) => {
  if (scene === "p1") return "Top step, trophy lift, flares, and confetti";
  if (scene === "podium") return `Podium, champagne spray, position ${position === 3 ? 3 : 2}`;
  if (scene === "points") return `Parc fermé points finish, position ${position}`;
  if (scene === "dnf") return "Did not finish, car pushed to the garage";
  return `Pit wall debrief, classified position ${position}`;
};

const staticDnfCar = (
  mode: MonzaV2Mode,
  palette: ReferencePalette,
  x: number,
  y: number,
  width: number,
  height: number,
) => {
  const body = mode === "notte" ? palette.ink : palette.acc;
  const sidepod = mode === "notte" ? palette.acc : "#A50D26";
  const highlight = mode === "notte" ? palette.gold : palette.gold;
  const scaleX = width / 196;
  const scaleY = height / 63.5;

  return `
    <g transform="translate(${x} ${y}) scale(${scaleX} ${scaleY})">
      <ellipse cx="44" cy="49" rx="15" ry="14" fill="${palette.ink}"></ellipse>
      <ellipse cx="44" cy="49" rx="6" ry="5.5" fill="${palette.bg}" stroke="${highlight}" stroke-width="2"></ellipse>
      <ellipse cx="154" cy="49" rx="15" ry="14" fill="${palette.ink}"></ellipse>
      <ellipse cx="154" cy="49" rx="6" ry="5.5" fill="${palette.bg}" stroke="${highlight}" stroke-width="2"></ellipse>
      <path d="M 8,42 L 24,31 L 72,29 L 98,17 L 124,17 L 138,28 L 169,32 L 184,38 L 194,40 L 194,50 L 12,50 Z" fill="${body}" stroke="${palette.ink}" stroke-width="2.5" stroke-linejoin="round"></path>
      <path d="M 73,30 L 103,20 L 133,29 L 121,45 L 70,45 Z" fill="${sidepod}"></path>
      <path d="M 104,19 Q 111,6 121,16 L 128,29 L 113,29 Z" fill="${palette.ink}"></path>
      <circle cx="117" cy="15" r="6.5" fill="${mode === "notte" ? palette.ink : palette.acc}" stroke="${palette.ink}" stroke-width="2"></circle>
      <path d="M 102,27 L 105,13 L 127,13 L 134,29" fill="none" stroke="${highlight}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"></path>
      <path d="M 18,31 L 8,22 L 11,18 L 31,27 L 31,42 L 22,42 Z" fill="${body}" stroke="${palette.ink}" stroke-width="2.5" stroke-linejoin="round"></path>
      <rect x="4" y="18" width="24" height="5" fill="${palette.ink}"></rect>
      <path d="M 166,38 L 191,35 L 196,39 L 196,44 L 165,45 Z" fill="${body}" stroke="${palette.ink}" stroke-width="2.5" stroke-linejoin="round"></path>
      <rect x="169" y="47" width="27" height="4.5" fill="${palette.ink}"></rect>
      <path d="M 59,30 L 91,25" stroke="${highlight}" stroke-width="2.4"></path>
      <path d="M 82,39 L 127,39" stroke="${palette.bg}" stroke-width="2" opacity="0.72"></path>
      <rect x="25" y="48" width="148" height="4" fill="${palette.ink}"></rect>
    </g>`;
};

const renderReferenceSvg = (
  mode: MonzaV2Mode,
  scene: FinishScene,
  position: number,
) => {
  const palette = PALETTES[mode];
  const language = mode === "notte" ? "notte" : "scuderia";
  const podiumPosition = position === 3 ? 3 : 2;
  const pointPosition = POINTS_BY_POSITION[position] ? position : 7;
  const pointValue = POINTS_BY_POSITION[pointPosition];
  const pid = `${language}-${scene}`;
  const dnfHeight = mode === "notte" ? 63.5 : 63.18;
  const dnfWidth = 196;
  const dnfX = 148;
  const dnfY = 166 - dnfHeight - 7.5;
  const dnfCapSize = 9.5;
  const dnfDotRad = 2.2;
  const dnfDotOffset = Number(
    (4.2 * dnfCapSize + 13 + 6 + dnfDotRad).toFixed(1),
  );

  const conditions = {
    isP1: scene === "p1",
    isPodium: scene === "podium",
    podOn2: podiumPosition === 2,
    podOn3: podiumPosition === 3,
    isPoints: scene === "points",
    isFinished: scene === "finished",
    isDnf: scene === "dnf",
    isScu: mode === "giorno",
    isNotte: mode === "notte",
    armHelmet: true,
    armHips: false,
    armCrossed: false,
  };

  const values: Record<string, string | number> = {
    pid,
    ptsAcc: mode === "notte" ? "#3DB36B" : "#1E7A46",
    ptsDx: 0,
    ptsDy: -30,
    sprayDx: 3,
    sprayDy: 11,
    dnfTilt: 4,
    dnfImgX: Number(dnfX.toFixed(2)),
    dnfImgY: Number(dnfY.toFixed(2)),
    dnfImgW: Number(dnfWidth.toFixed(2)),
    dnfImgH: Number(dnfHeight.toFixed(2)),
    dnfPivotX: Number((dnfX + 0.2 * dnfWidth).toFixed(2)),
    dnfSmokeDx: Number((dnfX + 0.55 * dnfWidth - 258).toFixed(2)),
    dnfSmokeDy: Number((dnfY + 2 - 105).toFixed(2)),
    dnfStampDx: 34,
    dnfStampDy: -11,
    dnfCapSize,
    dnfCapY: Number((104 + 0.9 * dnfCapSize).toFixed(1)),
    dnfDotCy: Number((104 + 0.58 * dnfCapSize).toFixed(1)),
    dnfDotRad,
    dnfDotL: Number((140 - dnfDotOffset).toFixed(1)),
    dnfDotR2: Number((140 + dnfDotOffset).toFixed(1)),
  };

  for (const [key, value] of Object.entries(palette)) {
    values[`c.${key}`] = value;
  }
  values["c.dg"] = `url(#dg${pid})`;
  values["c.sprayFill"] =
    mode === "notte" ? `url(#dg${pid})` : `url(#ds${pid})`;

  const pointsText = `+${pointValue}${pointValue === 1 ? " PT" : " PTS"}`;
  const positionText = `P${position}`;
  const dnfCar = staticDnfCar(
    mode,
    palette,
    Number(dnfX.toFixed(2)),
    Number(dnfY.toFixed(2)),
    Number(dnfWidth.toFixed(2)),
    Number(dnfHeight.toFixed(2)),
  );
  let markup = selectConditionalBlocks(REFERENCE_SVG_TEMPLATE, conditions)
    .replace(' ref="{{ ptsValRef }}"></text>', `>${escapeMarkup(pointsText)}</text>`)
    .replace(' ref="{{ ptsPosRef }}"></text>', `>${escapeMarkup(`P${pointPosition}`)}</text>`)
    .replace(' ref="{{ posRef }}"></text>', `>${escapeMarkup(positionText)}</text>`)
    .replace(' ref="{{ tagRef }}"></text>', `>${escapeMarkup(textForScene(scene, position))}</text>`)
    // The reference points to two PNGs that are absent from the handoff bundle.
    // This static vector occupies their exact source bounds without a failed request.
    .replace(/<image href="assets\/scene5\/dnf-car-(?:scuderia|notte)\.png"[^>]*><\/image>/, dnfCar)
    .replace(/\sstyle="animation:[^"]*"/g, "");

  markup = markup.replace(
    /{{\s*([^}]+?)\s*}}/g,
    (_match, key: string) => escapeMarkup(String(values[key] ?? "")),
  );

  return markup.replace("<svg ", '<svg aria-hidden="true" focusable="false" ');
};

export function FinishIllustration({
  mode,
  scene,
  position,
}: FinishIllustrationProps) {
  const palette = PALETTES[mode];
  const svgMarkup = renderReferenceSvg(mode, scene, position);

  return (
    <div
      role="img"
      aria-label={accessibleLabel(scene, position)}
      data-finish-mode={mode}
      data-finish-scene={scene}
      style={{
        background: palette.bg,
        display: "block",
        height: "100%",
        minHeight: "200px",
        overflow: "hidden",
        position: "relative",
        width: "100%",
      }}
      // The markup is a trusted, bundled copy of the reference SVG.
      dangerouslySetInnerHTML={{ __html: svgMarkup }}
    />
  );
}
